import React from "react";

const BorderBeam = React.forwardRef(
  (
    {
      className = "",
      size = 300,
      duration = 20,
      delay = 0,
      borderWidth = 1.5,
      colorFrom = "from-transparent",
      colorTo = "to-transparent",
      colorVia = "via-red-500",
    },
    ref
  ) => {
    return (
      <div
        ref={ref}
        className={`absolute inset-0 rounded-[3rem] overflow-hidden pointer-events-none ${className}`}
        style={{
          WebkitMaskImage: `radial-gradient(circle at center, transparent 50%, black 100%)`,
          maskImage: `radial-gradient(circle at center, transparent 50%, black 100%)`,
        }}
      >
        <div
          className={`absolute inset-0 rounded-[3rem] bg-gradient-to-r ${colorFrom} ${colorVia} ${colorTo}`}
          style={{
            animation: `borderBeamAnimation ${duration}s linear infinite`,
            animationDelay: `${delay}s`,
            borderRadius: "inherit",
            width: `${size}%`,
            height: `${size}%`,
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            opacity: 0.7,
          }}
        />
      </div>
    );
  }
);

BorderBeam.displayName = "BorderBeam";

export { BorderBeam };
